// src/components/SEO.tsx
import React from "react";
import { Helmet } from "react-helmet";
import { useTranslation } from "gatsby-plugin-react-i18next";
import type { UserProfile } from "../interfaces";

interface Props {
  data: UserProfile;

  /**
   * i18n keys (recommended) OR literal overrides
   *  titleKey="services.cwv.meta.title"
   *  descriptionKey="services.cwv.meta.description"
   *  keywordsKey="services.cwv.meta.keywords"
   */
  titleKey?: string;
  descriptionKey?: string;
  keywordsKey?: string;

  title?: string;
  description?: string;
  keywords?: string[];

  /**
   * Optional overrides for canonical and social
   */
  pathname?: string; // e.g. "/services/cwv/"
  canonical?: string; // full canonical override
  image?: string; // absolute URL preferred
  noindex?: boolean;

  /**
   * Schema overrides
   */
  schemaType?: "LocalBusiness" | "ProfessionalService" | "Organization";
  schemaName?: string; // defaults to data.name
}

const DEFAULT_OG_IMAGE = "https://riano.co/logo.png";

function compactObject<T extends Record<string, any>>(obj: T): T {
  // Remove undefined/null and empty arrays recursively (keeps 0/false/"" as-is)
  const isPlainObject = (v: any) => v && typeof v === "object" && !Array.isArray(v);

  const walk = (value: any): any => {
    if (Array.isArray(value)) {
      const cleaned = value.map(walk).filter((v) => v !== undefined && v !== null);
      return cleaned.length ? cleaned : undefined;
    }
    if (isPlainObject(value)) {
      const out: Record<string, any> = {};
      Object.entries(value).forEach(([k, v]) => {
        const cleaned = walk(v);
        if (cleaned !== undefined && cleaned !== null) out[k] = cleaned;
      });
      return Object.keys(out).length ? out : undefined;
    }
    return value;
  };

  return (walk(obj) ?? {}) as T;
}

const SEO: React.FC<Props> = ({
  data,
  titleKey,
  descriptionKey,
  keywordsKey,
  title,
  description,
  keywords,
  pathname,
  canonical,
  image,
  noindex,
  schemaType = "LocalBusiness",
  schemaName,
}) => {
  const { t, i18n } = useTranslation();

  const resolvedTitle =
    title ??
    (titleKey ? (t(titleKey) as string) : (t("keywords.general") as string)) ??
    "";

  const resolvedDescription =
    description ??
    (descriptionKey ? (t(descriptionKey) as string) : (t("keywords.pymes") as string)) ??
    "";

  // Pull keywords array from i18n JSON when provided
  const resolvedKeywords: string[] =
    keywords ??
    (keywordsKey ? (t(keywordsKey, { returnObjects: true }) as string[]) : []);

  // Canonical
  const siteUrl = (data?.url || "").replace(/\/$/, "");
  const resolvedCanonical =
    canonical ??
    (pathname
      ? `${siteUrl}${pathname.startsWith("/") ? "" : "/"}${pathname}`
      : siteUrl);

  const ogImage = image || DEFAULT_OG_IMAGE;

  // Schema: use keywords as "knowsAbout" (more semantic than meta keywords)
  const schemaMarkup = compactObject({
    "@context": "https://schema.org",
    "@type": schemaType,
    name: schemaName || data?.name || "Frontend Developer - Juan Pablo Riano",
    description: resolvedDescription,
    url: resolvedCanonical,
    image: ogImage,
    telephone: data?.phone,
    priceRange: "$$",
    openingHours: "Mo-Fr 09:00-17:00",

    // This is where your translation keywords become useful to search engines:
    knowsAbout: resolvedKeywords?.filter(Boolean),

    address: compactObject({
      "@type": "PostalAddress",
      streetAddress: data?.address,
      addressLocality: data?.city,
      addressRegion: data?.province,
      postalCode: data?.postalCode,
      addressCountry: data?.country === "Canada" ? "CA" : data?.country,
    }),

    geo: {
      "@type": "GeoCoordinates",
      latitude: 45.35475,
      longitude: -73.7376551,
    },

    sameAs: [data?.instagram, data?.facebook, data?.linkedIn].filter(Boolean),
  });

  return (
    <Helmet htmlAttributes={{ lang: i18n.language }}>
      <title>{resolvedTitle}</title>
      <meta name="description" content={resolvedDescription} />

      {/* Canonical */}
      {resolvedCanonical ? <link rel="canonical" href={resolvedCanonical} /> : null}

      {/* Robots */}
      {noindex ? <meta name="robots" content="noindex, nofollow" /> : null}

      {/* Open Graph */}
      <meta property="og:type" content="website" />
      <meta property="og:title" content={resolvedTitle} />
      <meta property="og:description" content={resolvedDescription} />
      {resolvedCanonical ? <meta property="og:url" content={resolvedCanonical} /> : null}
      {ogImage ? <meta property="og:image" content={ogImage} /> : null}

      {/* Twitter */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={resolvedTitle} />
      <meta name="twitter:description" content={resolvedDescription} />
      {ogImage ? <meta name="twitter:image" content={ogImage} /> : null}

      {/* Structured Data */}
      <script type="application/ld+json">{JSON.stringify(schemaMarkup)}</script>
    </Helmet>
  );
};

export default SEO;